@app.get('/api/gdpr-exports/{export_id}')
def download_gdpr_export(
    export_id: UUID,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user)
):
    export_job = db.query(GdprRequest).filter(GdprRequest.id == export_id, GdprRequest.user_id == current_user.id).first()
    if not export_job or export_job.status != 'COMPLETED':
        raise HTTPException(status_code=404, detail="Export archive not ready")

    return FileResponse(
        path=export_job.archive_path,
        filename=f"personal_data_{export_id}.zip",
        media_type="application/zip"
    )
